// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    // fuzz parameters: amount to send, and whether the adversarial receiver should revert
    function testFuzz_property(uint256 amount, bool shouldRevert) public {
        // keep amount in a reasonable range but allow zero to test requirement; wide domain
        amount = bound(amount, 0, 1 ether);

        // Deploy an adversarial counterparty whose fallback will revert when configured
        RevertingReceiver rec = new RevertingReceiver(shouldRevert);

        // fund the contract so it has Ether to send
        vm.deal(address(c), 1 ether);

        // the deciding call: owner (test contract) calls c.sendTo to the receiver
        // wrap in try/catch to observe whether the reference reverts (ok==false) or succeeds (ok==true)
        bool ok;
        try c.sendTo(address(rec), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): if the receiver is configured to revert on receive and
        // the inputs are admissible (caller is owner by construction, receiver != zero, amount > 0),
        // then the reference must not complete successfully (ok == false). This distinguishes the
        // mutant which ignores send() return and thus can return ok==true for such cases.
        if (shouldRevert && amount > 0 && address(rec) != address(0)) {
            assertTrue(!ok);
        } else {
            // otherwise we cannot assert a particular outcome for all inputs, so just assert true
            assertTrue(true);
        }
    }
}

// adversarial helper: reverts on receive when configured
contract RevertingReceiver {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("receive revert");
    }
}
